33	bt_status_t bt_sal_get_remote_address(struct bt_conn* conn, bt_address_t* addr)
34	{
35	    struct bt_conn_info info;
36	
37	    if (conn == NULL)
38	        return BT_STATUS_FAIL;
39	
40	    if (bt_conn_get_info(conn, &info) != 0) {
41	        BT_LOGE("%s, failed to get address", __func__);
42	        return BT_STATUS_FAIL;
43	    }
44	
45	    if (info.type == BT_CONN_TYPE_LE) {
46	        return get_le_addr_from_conn(conn, addr);
47	    }
48	
49	    bt_addr_set(addr, info.br.dst->val);
50	    return BT_STATUS_SUCCESS;
51	}
