53	bt_conn_info_t* bt_conn_find(const bt_address_t* addr, uint8_t transport)
54	{
55	    for (int i = 0; i < CONFIG_BT_MAX_CONN; i++) {
56	        if ((!bt_addr_compare(&g_conn_info[i].addr, addr))
57	            && (transport == g_conn_info[i].transport)) {
58	            return &g_conn_info[i];
59	        }
60	    }
61	
62	    return NULL;
63	}
